function setView(){const c=FW.config(FD()),ta=(n,l)=>`<textarea class="textarea" name="${n}" rows="8">${esc(l.join('\n'))}</textarea>`;
 return`<div class="grid grid-3">${P.card({title:'دسته‌های هزینه',body:ta('exp',c.expenseCategories)+'<span class="hint">هر خط یک دسته. دسته‌ای که سند دارد حذف نمی‌شود.</span>'})}${P.card({title:'دسته‌های درآمد',body:ta('inc',c.incomeCategories)})}${P.card({title:'دسته‌های بدهی و طلب',body:ta('obl',c.obligationCategories)})}</div>
 <div class="mt">${P.card({title:'مالیات',body:`<div class="form-grid">${P.field('مالیات بر ارزش افزوده (٪)',`<input class="input num" name="vat" value="${fa(c.vatPercent)}">`)}${P.field('ذخیرهٔ مالیات عملکرد (٪ فروش بدون ارزش افزوده)',`<input class="input num" name="res" value="${fa(c.performanceReservePercent)}">`)}</div>${P.toggle('vin','مبلغ فروش (کارتخوان و صندوق) شامل ارزش افزوده است',c.vatIncluded,'ارزش افزوده روی فاکتور اضافه می‌شود؛ در سود و زیان از فروش جدا و بدهی به دارایی حساب می‌شود')}`})}</div>
 <div class="toolbar mt">${canW()?`<button class="btn btn-primary" id="fsSave">${P.ic('save')}ذخیرهٔ تنظیمات مالی</button>`:`<button class="btn btn-secondary" disabled title="${esc(why())}">${P.ic('lock')}ذخیره</button>`}</div>`}
