// VAT of a month: for cash-report months the VAT Sepidz recorded (taxAmount, rial → toman), else the P&L's computed VAT
function monthVat(k,r){if(r.m?.salesSource!=='cash')return r.vat;try{const src=ledgerSrc(),CW=window.CashWrite,reps=CW?.reports?CW.reports(src.cash):A(src.cash?.reports).filter(x=>x.status!=='void');return reps.filter(x=>E.D(x.date).startsWith(k+'/')).reduce((a,x)=>a+(Number(x.taxAmount)||0),0)/10}catch(e){return r.vat}}
function pnlMount(root){const s=P.$('#plM',root);if(s)s.onchange=()=>{st.pm=s.value;P.render()}}

/* =================== staff meals (stage 7b) =================== */
st.mm='';st.mw=null;st.mwFor='';
const overnight=p=>p?.accommodation?.overnight===true;
function suggested(date){const hr=hrDoc();if(!hr)return null;const [y,m]=date.split('/').map(Number),plan=SWr?.planOf?.(hr,y,m),asg=plan?SWr.assignments(SWr.cleanCells(plan.cells)):{};let n=0;
 for(const p of A(hr.personnel)){if(overnight(p)&&p.status==='فعال'){n+=3;continue}if(!plan)continue;const v=SWr.dayValue(asg,p.id,date);n+=v==='me'?2:v==='m'||v==='e'?1:0}return plan||A(hr.personnel).some(overnight)?n:null}
function mealDays(k){const [y,m]=k.split('/').map(Number),len=window.PayrollCore?.monthLength?.(y,m)||(m<=6?31:30),out=[];for(let d=1;d<=len;d++){const x=`${k}/${String(d).padStart(2,'0')}`;if(x>today())break;out.push(x)}return out}
function ensureMeals(k){if(st.mw&&st.mwFor===k)return;st.mwFor=k;st.mw={};for(const x of FW.mealsOfMonth(FD(),k))st.mw[x.date]={portions:String(x.portions),notes:x.notes||''}}
const mealDirty=()=>{if(!st.mw)return false;const k=st.mwFor,cur=Object.fromEntries(FW.mealsOfMonth(FD(),k).map(x=>[x.date,x]));return mealDays(k).some(d=>{const a=st.mw[d]||{portions:'',notes:''},b=cur[d];return S(a.portions)!==(b?String(b.portions):'')||S(a.notes)!==S(b?.notes)})};
/* cost of each day: staff-meal purchases dated that day + stock taken as «مصرف پرسنلی» that day (inventory engine, at cost) */
let mealDayKey='',mealDayData=null;
function mealDayCosts(k){const inv=window.InvControl?.state,key=k+'|'+(inv?.raw?.inventory?.meta?.serverSaveToken||'')+'|'+A(FD()?.entries).length;if(key===mealDayKey&&mealDayData)return mealDayData;
 const buy={},stock={},items={};for(const e of A(FD()?.entries))if(e.type==='expense'&&e.category===FW.STAFF_MEAL&&FW.active(e)&&S(e.date).startsWith(k+'/')){buy[e.date]=(buy[e.date]||0)+(Number(e.amountToman)||0);(items[e.date]=items[e.date]||[]).push(e)}
 try{const E=window.InvEngine,M=inv?.M;if(M){const r=E.monthRange(k),Pd=E.analyze(M,r.from,r.to>today()?today():r.to,{fixUnits:true});for(const ev of A(Pd.wasteEvents))if(ev.resp==='staff'&&ev.value)stock[E.D(ev.date)]=(stock[E.D(ev.date)]||0)+ev.value}}catch(_){}
 mealDayKey=key;mealDayData={buy,stock,items};return mealDayData}
/* staff-meal purchase: lines (item, quantity, amount) → one «غذای پرسنل» expense paid from an account; lines kept on the entry */
function mealBuyForm(){const row=()=>`<div class="row mb-l" style="gap:6px;margin-bottom:6px"><input class="input" placeholder="قلم (مثلاً برنج، مرغ)" style="flex:2"><input class="input" placeholder="مقدار و واحد" style="flex:1"><input class="input num" placeholder="مبلغ" style="flex:1" inputmode="numeric" data-money></div>`;
 form({title:'خرید غذای پرسنل',size:'lg',ok:'ذخیره روی سرور',body:`<div class="form-grid">${P.field('تاریخ *',dateIn())}${P.field('از حساب *',accSel())}</div><h4>اقلام</h4><div id="mbL">${row()}${row()}${row()}</div><button type="button" class="btn btn-ghost btn-sm" id="mbAdd">${P.ic('plus')}ردیف</button><div class="sum-box mt"><span>جمع</span><b id="mbT">۰</b></div>${P.field('توضیح','<input class="input" name="notes">')}${P.note('به‌عنوان هزینه با دستهٔ «غذای پرسنل» در «هزینه‌ها» ثبت می‌شود و در هزینهٔ همان روز غذای پرسنل حساب می‌شود. موادی که از انبار رستوران برمی‌دارید را با «ثبت پرتی / مصرف» و نوع «مصرف پرسنلی» ثبت کنید؛ آن مقدار در مغایرت انبار نمی‌آید و در هزینهٔ غذای پرسنل می‌آید.','info')}`,
  onMount:m=>{const tot=()=>{const s=[...m.querySelectorAll('.mb-l')].reduce((a,r)=>a+(P.num(r.children[2].value)||0),0);P.$('#mbT',m).textContent=P.mt(s)};P.$('#mbAdd',m).onclick=()=>{P.$('#mbL',m).insertAdjacentHTML('beforeend',row())};m.addEventListener('input',tot)},
  onSave:(m,btn)=>{const lines=[...m.querySelectorAll('.mb-l')].map(r=>({item:r.children[0].value.trim(),qty:r.children[1].value.trim(),amountToman:P.num(r.children[2].value)||0})).filter(l=>l.item||l.amountToman);if(!lines.length)throw Error('حداقل یک قلم وارد کنید');if(lines.some(l=>!l.item||!(l.amountToman>0)))throw Error('برای هر ردیف نام قلم و مبلغ لازم است');
   const acc=v(m,'acc'),date=E.D(P.en(v(m,'date'))),x={type:'expense',date,category:FW.STAFF_MEAL,amountToman:lines.reduce((a,l)=>a+l.amountToman,0),title:'خرید غذای پرسنل: '+lines.map(l=>l.item).join('، ').slice(0,120),notes:v(m,'notes'),expenseMonth:date.slice(0,7),spreadMonths:1,paid:true,accountKey:acc};
   save(btn,{action:'STAFF_MEAL_PURCHASE_ADDED',details:{lines:lines.length},mutate:(d,c)=>{const e=FW.addEntry(d,c,x,{accountName:accName(acc).replace(/^[^:]+: /,'')});e.items=lines;return e},done:e=>`خرید غذای پرسنل ${P.mt(e.amountToman)} ${P.U()} ثبت شد`})}})}
function mealsView(){const k=st.mm||(st.mm=today().slice(0,7));ensureMeals(k);const dc=mealDayCosts(k);const days=mealDays(k),stock=(DR()?.months?.()||[]).find(x=>x.k===k)?.staffUse,c=FW.mealCost(FD(),k,stock),hr=hrDoc(),nOver=A(hr?.personnel).filter(p=>overnight(p)&&p.status==='فعال').length,d=mealDirty();
 const trend=(DR()?.months?.()||[]).slice(-6).map(x=>{const q=FW.mealCost(FD(),x.k,x.staffUse);return[esc(ML(x.k)),fa(q.portions),T(q.docs),T(q.stock),`<b>${T(q.total)}</b>`,q.perPortion?T(q.perPortion):'—']}).reverse();
 return`<div class="toolbar" style="gap:8px;flex-wrap:wrap;margin-bottom:var(--s3)"><select class="select" id="mlM" style="width:auto">${monthsList().map(x=>`<option value="${x}" ${x===k?'selected':''}>${ML(x)}</option>`).join('')}</select>${d?P.b('تغییر ذخیره‌نشده','danger',1):''}<span class="grow"></span>
  ${canW()?`<button class="btn btn-secondary btn-sm" id="mlBuy">${P.ic('shopping-basket')}خرید غذای پرسنل</button><button class="btn btn-secondary btn-sm" id="mlFill">${P.ic('wand-2')}پر کردن روزهای خالی با پیشنهاد</button><button class="btn btn-primary btn-sm" id="mlSave" ${d?'':'disabled'}>${P.ic('save')}ذخیره</button><button class="btn btn-ghost btn-sm" id="mlUndo" ${d?'':'disabled'}>انصراف</button>`:''}</div>
 <div class="grid grid-4">${P.kpi({label:'پرس '+ML(k),icon:'utensils',value:fa(c.portions),foot:`${fa(c.days)} روز ثبت از ${fa(days.length)}`})}${P.kpi({label:'هزینهٔ غذای پرسنل',icon:'receipt',value:P.mShort(c.total),unit:P.unitName(),foot:`خرید ${T(c.docs)} · از انبار ${T(c.stock)}`})}${P.kpi({label:'بهای هر پرس',icon:'calculator',value:c.perPortion?P.mShort(c.perPortion):'—',unit:c.perPortion?P.unitName():''})}${P.kpi({label:'شب‌خواب',icon:'bed',value:fa(nOver),foot:'روزی ۳ وعده در پیشنهاد'})}</div>
 ${nOver?'':`<div class="mt">${P.note('هیچ پرسنلی «شب‌خواب» علامت نخورده است؛ در پروندهٔ هر نفر ← اطلاعات و جایگاه علامت بزنید تا پیشنهاد روزانه درست شود.','info')}</div>`}
 <div class="grid grid-3 mt"><div class="span-2">${P.card({title:'پرس هر روز',sub:'پیشنهاد = هر شیفت شیفت‌پلن یک پرس (دو شیفت دو پرس) و هر شب‌خواب سه پرس؛ تعداد واقعی را با پرس‌های اضافه (مثلاً مدیران) وارد کنید.',flush:1,body:`<div class="table-wrap"><table class="table"><thead><tr><th>تاریخ</th><th>روز</th><th class="num">پیشنهاد</th><th class="num">پرس</th><th class="num">خرید</th><th class="num">از انبار</th><th class="num">هزینهٔ روز</th><th class="num">هر پرس</th><th>توضیح</th></tr></thead><tbody>${days.slice().reverse().map(x=>{const s=suggested(x),v=st.mw[x]||{portions:'',notes:''},b=dc.buy[x]||0,sk=dc.stock[x]||0,pr=Number(P.en(v.portions))||0;return`<tr><td>${fa(x)}</td><td>${esc(window.RayoAttendanceCore?.weekdayName?.(x)||'')}</td><td class="num muted">${s===null?'—':fa(s)}</td><td><input class="input num ml-i" style="width:70px" data-d="${x}" data-f="portions" value="${esc(fa(v.portions))}" inputmode="numeric" ${canW()?'':'disabled'}></td><td class="num" title="${esc(A(dc.items[x]).map(e=>A(e.items).map(l=>l.item+' '+(l.qty||'')).join('، ')||e.title).join(' | '))}">${b?T(b):'—'}</td><td class="num">${sk?T(sk):'—'}</td><td class="num"><b>${b+sk?T(b+sk):'—'}</b></td><td class="num">${pr&&b+sk?T((b+sk)/pr):'—'}</td><td><input class="input ml-i" data-d="${x}" data-f="notes" value="${esc(v.notes)}" ${canW()?'':'disabled'}></td></tr>`}).join('')}</tbody></table></div>`})}</div>
 <div class="stack">${P.card({title:'روند ماه‌ها',flush:1,body:P.table(['ماه',{t:'پرس',n:1},{t:'خرید',m:1},{t:'از انبار',m:1},{t:'کل',m:1},{t:'هر پرس',m:1}],trend)})}${P.note('خرید مخصوص غذای پرسنل را با «خرید غذای پرسنل» (اقلام و مبلغ) و برداشت از انبار رستوران را با «ثبت پرتی / مصرف» نوع «مصرف پرسنلی» ثبت کنید؛ برداشت از انبار در مغایرت نمی‌آید و جدا در «از انبار» دیده می‌شود.','info')}</div></div>`}
function mealsMount(root){const k=st.mm;const s=P.$('#mlM',root);if(s)s.onchange=()=>{if(mealDirty()&&!confirm('تغییرات ذخیره‌نشده از بین می‌رود. ادامه؟')){s.value=k;return}st.mm=s.value;st.mw=null;P.render()};
 const upd=()=>{const dd=mealDirty(),a=P.$('#mlSave',root),b=P.$('#mlUndo',root);if(a)a.disabled=!dd;if(b)b.disabled=!dd};
 P.$$('.ml-i',root).forEach(i=>i.oninput=()=>{const x=i.dataset.d;st.mw[x]=st.mw[x]||{portions:'',notes:''};st.mw[x][i.dataset.f]=i.dataset.f==='portions'?P.en(i.value):i.value;upd()});
 const on=(id,f)=>{const x=P.$('#'+id,root);if(x)x.onclick=f};on('mlUndo',()=>{st.mw=null;P.render()});on('mlBuy',mealBuyForm);
 on('mlFill',()=>{let n=0;for(const x of mealDays(k)){const v=st.mw[x];if(v&&S(v.portions)!=='')continue;const sg=suggested(x);if(sg===null)continue;st.mw[x]={portions:String(sg),notes:v?.notes||''};n++}P.render();P.toast(n?`${fa(n)} روز با پیشنهاد پر شد؛ برای ثبت «ذخیره» بزنید`:'روز خالیِ قابل پیشنهاد نیست',n?'check':'info')});
 on('mlSave',()=>{if(!canW())return P.toast(why(),'lock');const cur=Object.fromEntries(FW.mealsOfMonth(FD(),k).map(x=>[x.date,x])),rows={};for(const x of mealDays(k)){const a=st.mw[x]||{portions:'',notes:''},b=cur[x];if(S(a.portions)!==(b?String(b.portions):'')||S(a.notes)!==S(b?.notes))rows[x]={portions:a.portions,notes:a.notes,suggested:suggested(x)??''}}const t=today();
  save(P.$('#mlSave',root),{action:'STAFF_MEALS_SAVED',details:{month:k},mutate:(d,c)=>FW.saveMeals(d,c,{rows,today:t}),done:n=>{st.mw=null;P.render();return`پرس ${fa(n)} روز ذخیره شد`}})})}
window.addEventListener('beforeunload',e=>{if(mealDirty()){e.preventDefault();e.returnValue=''}});

/* =================== accounts and flows (stage 7c) =================== */
const TYPE_L={card:'کارت / حساب',cash:'نقد نزد',place:'محل پرداخت',petty:'کارت تنخواه',pos:'کارتخوان',unknown:'نامشخص'};
const WHERE_L={card:'صندوق ← تنظیمات صندوق',cash:'صندوق ← تنظیمات صندوق',place:'تنظیمات ← محل‌های پرداخت',petty:'مالی ← تنخواه'};
const SRC_L={pos:'کارتخوان',cardToCard:'کارت به کارت صندوق',cashDelivery:'نقد صندوق',custody:'وجه نزد اشخاص',ledger:'سند مالی',settlement:'بدهی / طلب',payroll:'پرسنل',supplier:'تأمین‌کننده',transfer:'انتقال',petty:'تنخواه'};
st.af='';st.at='';
const ledgerSrc=()=>({fin:FD(),cash:IC.state.raw?.cashreport,inv:IC.state.raw?.inventory,hr:hrDoc()});
/* bank-like accounts for the card machines: cards / accounts and payment places, not merged duplicates */
const posChoices=src=>FW.accountRows(src).filter(r=>(r.type==='card'||r.type==='place')&&!r.aliasOf&&(r.active||r.pos));
const posSelect=(src,cur)=>`<select class="select ac-pos" aria-label="حساب بانکی کارتخوان‌ها" style="width:auto;display:inline-block"><option value="">انتخاب</option>${posChoices(src).map(c=>`<option value="${esc(c.key)}" ${c.key===cur?'selected':''}>${esc(TYPE_L[c.type]+': '+c.name)}</option>`).join('')}</select>`;
const aliasLine=r=>{const o=A(r.aliases).filter(a=>S(a.name)!==S(r.name));return o.length?`<small class="muted" style="display:block">همان حساب: ${o.map(a=>esc(a.name)).join('، ')}</small>`:''};
function accountsView(){const t=today();if(!st.at)st.at=t;if(!st.af)st.af=t.slice(0,8)+'01';const src=ledgerSrc(),rows=FW.accountLedger(src,{from:st.af,to:st.at}),pos=FW.resolveKey(FD(),FD().settings?.posAccountKey),s=k=>rows.reduce((a,r)=>a+r[k],0);
 return`${pos?'':P.note('<b>حساب بانکیِ کارتخوان‌ها تعیین نشده است.</b> همهٔ کارتخوان‌ها به یک حساب وصل‌اند؛ آن را انتخاب کنید تا پول کارتخوان در ماندهٔ همان حساب بیاید. اگر یک حساب در دو فهرست با دو نام آمده، پایین صفحه در «مدیریت حساب‌ها» آن دو را یکی کنید.'+(canW()?' '+posSelect(src,''):''),'landmark')}
 <div class="toolbar" style="gap:8px;flex-wrap:wrap;align-items:center;margin:var(--s3) 0"><span class="muted">از</span><input class="input num" id="acF" style="width:120px" value="${fa(st.af)}" aria-label="از"><span class="muted">تا</span><input class="input num" id="acT" style="width:120px" value="${fa(st.at)}" aria-label="تا"><span class="grow"></span>${canW()?`<button class="btn btn-secondary btn-sm" id="acOpen">${P.ic('flag')}ماندهٔ اول حساب</button><button class="btn btn-primary btn-sm" id="acTr">${P.ic('arrow-left-right')}انتقال بین حساب‌ها</button>`:''}</div>
 <div class="grid grid-3">${P.kpi({label:'ورود به حساب‌ها',icon:'arrow-down-left',value:P.mShort(s('in')),unit:P.unitName(),foot:'در بازه'})}${P.kpi({label:'خروج از حساب‌ها',icon:'arrow-up-right',value:P.mShort(s('out')),unit:P.unitName()})}${P.kpi({label:'جمع مانده‌ها',icon:'wallet',value:P.mShort(s('balance')),unit:P.unitName(),foot:rows.some(r=>!r.opening&&r.type!=='petty'&&r.moves.length)?'بعضی حساب‌ها ماندهٔ اول ندارند':''})}</div>
 <div class="mt">${P.card({title:'حساب‌ها',sub:'روی هر حساب بزنید تا گردش آن را ببینید. تعریف، ویرایش و یکی کردن حساب‌ها در «مدیریت حساب‌ها» پایین همین صفحه است.',flush:1,
  body:P.table(['حساب','نوع','ماندهٔ اول',{t:'ابتدای بازه',m:1},{t:'ورود',m:1},{t:'خروج',m:1},{t:'مانده',m:1}],rows.map(r=>({cls:'click',attr:`data-acc="${esc(r.key)}"`,c:[`<b>${esc(r.name)}</b>${r.pos||r.key==='pos:'?' '+P.b('کارتخوان‌ها','info',1):''}${aliasLine(r)}`,esc(TYPE_L[r.type]||r.type),r.opening?`${T(r.opening.amount)} <small class="muted">${fa(r.opening.date)}</small>`:r.type==='petty'?'<span class="muted">در کارت تنخواه</span>':'<span class="muted">ثبت نشده</span>',T(r.start),T(r.in),T(r.out),`<b class="${r.balance<0?'down':''}">${r.balance<0?'−'+T(-r.balance):T(r.balance)}</b>`]})),{foot:['جمع','','',T(s('start')),T(s('in')),T(s('out')),T(s('balance'))],empty:'حسابی تعریف نشده'})})}</div>
 <div class="mt">${manageCard(src,pos)}</div>`}
/* ---------- managing the accounts: every record of the three lists (+ petty cards) in one place ----------
   Each record stays in the module that owns it (cash report, inventory settings, finance petty cash); this card opens
   that module's own form. Merging two records of one real account is finance.settings.accountAliases. */
function manageCard(src,pos){const all=FW.accountRows(src),byKey=new Map(all.map(r=>[r.key,r])),order={card:1,place:2,cash:3,petty:4};
 const btn=(id,ic,l)=>`<button class="btn btn-secondary btn-sm" id="${id}">${P.ic(ic)}${l}</button>`;
 return P.card({title:'مدیریت حساب‌ها',sub:'هر حساب در فهرست مالک خودش نگه داشته می‌شود و «ویرایش» همان فرم را باز می‌کند. اگر یک حساب واقعی در دو فهرست آمده (مثلاً «پاسارگاد - مهران» و «کارت به کارت مهران»)، «یکی کردن» گردش و ماندهٔ هر دو را زیر یک نام جمع می‌کند؛ هیچ ثبتی تغییر نمی‌کند و با «جدا کردن» برمی‌گردد. «نقد نزد» یعنی نقد صندوق دست چه کسی است.',flush:1,
  actions:`<span class="row" style="gap:6px;flex-wrap:wrap">${canW()?btn('amMerge','merge','یکی کردن دو حساب'):''}${btn('amCard','credit-card','کارت / حساب تازه')}${btn('amPerson','user-plus','شخص تازه (نقد نزد)')}${btn('amPlaces','wallet','محل‌های پرداخت')}</span>`,
  body:`<div style="padding:var(--s3) var(--s4)"><span class="muted">حساب بانکی کارتخوان‌ها:</span> ${canW()?posSelect(src,pos):esc(byKey.get(pos)?.name||'تعیین نشده')} <small class="muted">— پول همهٔ کارتخوان‌ها (همهٔ روزها) در ماندهٔ این حساب می‌آید؛ هر وقت حساب عوض شد همین‌جا تغییر دهید.</small></div>`
   /* one row per real account; its records in the other lists (merged) are listed inside the row with «جدا کردن» */
   +P.table(['حساب','نوع','وضعیت','در فهرست‌های دیگر هم',{t:'',noSort:1}],all.filter(r=>!r.aliasOf).sort((a,b)=>(order[a.type]||9)-(order[b.type]||9)||(b.active-a.active)||S(a.name).localeCompare(S(b.name),'fa')).map(r=>
    [`<b>${esc(r.name)}</b>${r.pos?' '+P.b('کارتخوان‌ها','info',1):''}<small class="muted" style="display:block">${esc(WHERE_L[r.type]||'')}</small>`,esc(TYPE_L[r.type]||r.type),r.active?P.b('فعال','success',1):P.b(r.type==='petty'?'بسته':'غیرفعال','neutral',1),
     A(r.aliases).length?r.aliases.map(a=>`<div style="white-space:nowrap"><small>${esc(TYPE_L[a.type]+': '+a.name)}</small>${canW()?` <a href="#" data-amsplit="${esc(a.key)}" style="font-size:12px">جدا کردن</a>`:''}</div>`).join(''):'—',
     `<button class="btn btn-ghost btn-sm" data-amed="${esc(r.key)}">${P.ic('pencil')}ویرایش</button>`]),{cls:'no-grid',empty:'حسابی تعریف نشده'})})}
function editAccount(key){const [kind,id]=[key.slice(0,key.indexOf(':')),key.slice(key.indexOf(':')+1)],CR=window.CashReal;
 if(kind==='account')return CR?.accountForm?CR.accountForm(id):P.toast('فرم صندوق بارگذاری نشده است','alert-triangle');
 if(kind==='cash')return CR?.personForm?CR.personForm(id):P.toast('فرم صندوق بارگذاری نشده است','alert-triangle');
 if(kind==='payment')return window.SettingsReal?.payForm?window.SettingsReal.payForm():P.toast('فرم محل‌های پرداخت بارگذاری نشده است','alert-triangle');
 if(kind==='petty')return window.PettyEntry?.card?window.PettyEntry.card(id):P.toast('فرم تنخواه بارگذاری نشده است','alert-triangle')}
function mergeForm(){const src=ledgerSrc(),all=FW.accountRows(src).filter(r=>!r.aliasOf),rows=all.filter(r=>r.type!=='petty'),bal=new Map(FW.accountLedger(src,{to:today()}).map(r=>[r.key,r])),opt=(n,list)=>`<select class="select" name="${n}"><option value="">انتخاب</option>${list.map(r=>`<option value="${esc(r.key)}">${esc(TYPE_L[r.type]+': '+r.name)}</option>`).join('')}</select>`;
 if(rows.length<2)return P.toast('دست‌کم دو حساب لازم است','info');
 form({title:'یکی کردن دو حساب',ok:'یکی کن',body:`<div class="form-grid">${P.field('حساب اصلی (نامی که می‌ماند) *',opt('to',all))}${P.field('همان حساب با نام دیگر *',opt('from',rows.filter(r=>!A(r.aliases).length)))}</div><div id="amPrev" style="font-size:13px"></div>${P.note('هیچ ثبتی در صندوق، خرید یا مالی تغییر نمی‌کند و شناسه‌ها همان می‌مانند. از این به بعد گردش، ماندهٔ اول و تنظیمات «نام دیگر» زیر حساب اصلی حساب می‌شود و در فرم‌های تازهٔ مالی فقط حساب اصلی پیشنهاد می‌شود. با «جدا کردن» به حالت قبل برمی‌گردد.','info')}`,
  onMount:m=>{const b=P.$('.modal-body',m)||m,show=()=>{const f=v(m,'from'),t=v(m,'to'),rf=bal.get(f),rt=bal.get(t);P.$('#amPrev',b).innerHTML=f&&t?(f===t?'<span class="neg">دو حساب یکی است</span>':`ماندهٔ «${esc(rt?.name||t)}»: ${T(rt?.balance||0)} + ماندهٔ «${esc(rf?.name||f)}»: ${T(rf?.balance||0)} = <b>ماندهٔ حساب یکی‌شده ${T((rt?.balance||0)+(rf?.balance||0))} ${P.U()}</b>${rf?.opening&&rt?.opening?' <span class="neg">— هر دو «ماندهٔ اول» دارند؛ اول یکی را ابطال کنید</span>':''}`):''};b.addEventListener('change',show)},
  onSave:(m,btn)=>{const x={fromKey:v(m,'from'),toKey:v(m,'to')};save(btn,{action:'FINANCE_ACCOUNTS_MERGED',details:x,mutate:(d,c)=>FW.setAlias(d,c,x),done:()=>'دو حساب یکی شد'})}})}
function splitAccount(key){if(!canW())return P.toast(why(),'lock');const r=FW.accountRows(ledgerSrc()).find(x=>x.key===key);if(!confirm(`«${r?.name||key}» دوباره حساب جدا شود؟`))return;const b=document.createElement('button');document.body.appendChild(b);
 save(b,{action:'FINANCE_ACCOUNTS_SPLIT',details:{fromKey:key},mutate:(d,c)=>FW.removeAlias(d,c,{fromKey:key}),done:()=>'حساب جدا شد'}).finally(()=>b.remove())}
function accountDetail(key){const r=FW.accountLedger(ledgerSrc(),{from:st.af,to:st.at}).find(x=>x.key===key);if(!r)return;let run=r.start;const rk=k=>FW.resolveKey(FD(),k),tr=A(FD().entries).filter(e=>FW.active(e)&&e.type==='transfer'&&(rk(e.fromKey)===key||rk(e.toKey)===key)).map(e=>e.id);
 P.modal({title:'گردش '+esc(r.name),size:'wide',body:`<div class="minis"><div class="mini"><small>ابتدای بازه</small><b>${T(r.start)}</b></div><div class="mini"><small>ورود</small><b>${T(r.in)}</b></div><div class="mini"><small>خروج</small><b>${T(r.out)}</b></div><div class="mini"><small>مانده</small><b>${T(r.balance)}</b></div></div>
  <div class="table-wrap mt" style="max-height:56vh;overflow:auto">${P.table(['تاریخ','شرح','منبع',{t:'ورود',m:1},{t:'خروج',m:1},{t:'مانده',m:1},''],r.moves.map(m=>{run+=m.amount;return[fa(m.date),esc(m.desc),esc(SRC_L[m.source]||m.source),m.amount>0?T(m.amount):'',m.amount<0?T(-m.amount):'',T(run),m.source==='transfer'&&canW()&&tr.includes(m.ref)?`<button class="btn btn-ghost btn-sm" data-vtr="${esc(m.ref)}">ابطال</button>`:'']}),{empty:'گردشی در این بازه نیست'})}</div>${r.opening&&r.type!=='petty'&&canW()?`<p class="muted" style="font-size:12px">ماندهٔ اول ${T(r.opening.amount)} در ${fa(r.opening.date)} — <a href="#" data-vop="${esc(r.opening.id)}">ابطال</a></p>`:''}`,
  onMount:m=>m.addEventListener('click',e=>{const b=e.target.closest('[data-vtr],[data-vop]');if(!b)return;e.preventDefault();P.close();voidForm(b.dataset.vtr?'ابطال انتقال':'ابطال ماندهٔ اول','',(d,c,rs)=>FW.voidTransfer(d,c,{id:b.dataset.vtr||b.dataset.vop,reason:rs}),'ابطال شد')})})}
const allAcc=()=>FW.accountRows(ledgerSrc()).filter(r=>r.active&&!r.aliasOf&&r.type!=='petty').map(r=>[r.key,`${TYPE_L[r.type]}: ${r.name}`]);
const accSel2=(n,sel='')=>`<select class="select" name="${n}"><option value="">انتخاب</option>${allAcc().map(([k,l])=>`<option value="${esc(k)}" ${k===sel?'selected':''}>${esc(l)}</option>`).join('')}</select>`;
function transferForm(pre={}){form({title:pre.title||'انتقال بین حساب‌ها',ok:'ذخیره روی سرور',body:`<div class="form-grid">${P.field('از *',accSel2('from',pre.from||''))}${P.field('به *',accSel2('to',pre.to||''))}${P.field('مبلغ *',P.money('amt',''))}${P.field('تاریخ *',dateIn())}</div>${P.field('توضیح','<input class="input" name="notes" placeholder="مثلاً واریز نقد مهران به حساب">')}${P.note('انتقال سود یا هزینه نیست؛ فقط جای پول را عوض می‌کند (مثلاً نقدی که نزد کسی است به حساب بانک واریز شود).','info')}`,
 onSave:(m,btn)=>{const n=k=>allAcc().find(x=>x[0]===k)?.[1]||'',x={fromKey:v(m,'from'),toKey:v(m,'to'),fromName:n(v(m,'from')),toName:n(v(m,'to')),amountToman:P.num(v(m,'amt')),date:E.D(P.en(v(m,'date'))),notes:v(m,'notes')};save(btn,{action:'FINANCE_TRANSFER_ADDED',details:{},mutate:(d,c)=>FW.addTransfer(d,c,x),done:e=>`انتقال ${P.mt(e.amountToman)} ${P.U()} ثبت شد`})}})}
function openingForm(){form({title:'ماندهٔ اول حساب',ok:'ذخیره روی سرور',body:`<div class="form-grid">${P.field('حساب *',accSel2('acc'))}${P.field('تاریخ *',dateIn('date',today().slice(0,8)+'01'),'مانده در ابتدای این روز')}${P.field('مبلغ *',`<input class="input num" name="amt" placeholder="منفی هم می‌شود" data-money>`)}</div>${P.field('شرح *','<input class="input" name="notes" placeholder="مثلاً طبق صورت‌حساب بانک / شمارش نقد">')}${P.note('گردش‌های قبل از این تاریخ داخل همین مانده حساب می‌شوند. ماندهٔ تازه جای قبلی را می‌گیرد و قبلی ابطال‌شده می‌ماند.','info')}`,
 onSave:(m,btn)=>{const raw=P.en(v(m,'amt')).replace(/[٬,\s]/g,''),x={accountKey:v(m,'acc'),date:E.D(P.en(v(m,'date'))),amountToman:raw===''?NaN:Number(raw),notes:v(m,'notes')};save(btn,{action:'FINANCE_OPENING_SET',details:{accountKey:x.accountKey},mutate:(d,c)=>FW.setOpening(d,c,x),done:()=>'ماندهٔ اول ثبت شد'})}})}
function accountsMount(root){const on=(id,f)=>{const x=P.$('#'+id,root);if(x)x.onclick=f};on('acTr',transferForm);on('acOpen',openingForm);
 for(const [id,k] of [['acF','af'],['acT','at']]){const i=P.$('#'+id,root);if(i)i.onchange=()=>{const d=E.D(P.en(i.value));if(d){st[k]=d;P.render()}}}
 P.$$('.ac-pos',root).forEach(ps=>ps.onchange=()=>{if(!ps.value)return;const k=ps.value;if(S(FD().settings?.posAccountKey)&&!confirm('حساب کارتخوان‌ها عوض شود؟ پول کارتخوانِ همهٔ روزهای گذشته هم به حساب تازه می‌رود.')){P.render();return}save(ps,{action:'FINANCE_POS_ACCOUNT_SET',details:{},mutate:(d,c)=>FW.setPosAccount(d,c,{accountKey:k}),done:()=>'حساب کارتخوان‌ها تعیین شد'})});
 on('amMerge',mergeForm);on('amCard',()=>window.CashReal?.accountForm?window.CashReal.accountForm():P.toast('فرم صندوق بارگذاری نشده است','alert-triangle'));on('amPerson',()=>window.CashReal?.personForm?window.CashReal.personForm():P.toast('فرم صندوق بارگذاری نشده است','alert-triangle'));on('amPlaces',()=>editAccount('payment:'));
 (P.$('#pnTab',root)||root).addEventListener('click',e=>{const ed=e.target.closest('[data-amed]');if(ed){e.stopPropagation();return editAccount(ed.dataset.amed)}const sp=e.target.closest('[data-amsplit]');if(sp){e.preventDefault();e.stopPropagation();return splitAccount(sp.dataset.amsplit)}const r=e.target.closest('[data-acc]');if(r)accountDetail(r.dataset.acc)})}

